'use client'

import React, { useState } from 'react'
import { Image as ImageIcon, Sparkles, Heart, Calendar, Filter } from 'lucide-react'

export default function GalleryView({ islandName }: { islandName: string }) {
    const [filter, setFilter] = useState('All')

    // Sample photo memories to give the gallery instant charm
    const memories = [
        { id: 1, title: 'Lavender Path View', date: '19 Sep 2026', tag: 'Scenery', gradient: 'from-[#4A3556] via-[#6D517D] to-[#9B77AD]', likes: 14 },
        { id: 2, title: 'Stargazing with Marshal', date: '15 Sep 2026', tag: 'Residents', gradient: 'from-[#3D3044] via-[#52435C] to-[#7A508C]', likes: 28 },
        { id: 3, title: 'Museum Entrance Waterfall', date: '12 Sep 2026', tag: 'Scenery', gradient: 'from-[#5C3D6B] via-[#8A629B] to-[#C2A5D3]', likes: 19 },
        { id: 4, title: 'Sherb Resting by the River', date: '10 Sep 2026', tag: 'Residents', gradient: 'from-[#2A2030] via-[#4A3556] to-[#6D517D]', likes: 32 },
    ]

    const filteredMemories = memories.filter(m => {
        if (filter === 'All') return true
        return m.tag === filter
    })

    return (
        <div className="space-y-6 max-w-6xl">
            {/* Top Stat Cards Row */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="p-6 bg-white rounded-3xl border border-[#E4DFEA] shadow-xs space-y-3">
                    <div className="flex justify-between items-center">
                        <span className="text-xs font-semibold text-[#665773]">Album Storage</span>
                        <span className="text-xs font-bold text-[#7A508C] bg-[#F4EEF8] px-2.5 py-1 rounded-full">{memories.length} / 50 Snaps</span>
                    </div>
                    <div className="w-full bg-[#F6F4F8] h-3 rounded-full overflow-hidden border border-[#E4DFEA]">
                        <div className="bg-gradient-to-r from-[#7A508C] to-[#9B77AD] h-full transition-all duration-500" style={{ width: `${(memories.length / 50) * 100}%` }}></div>
                    </div>
                    <p className="text-[11px] text-[#93859E]">Capture your favorite moments around {islandName} 📸</p>
                </div>

                <div className="p-6 bg-white rounded-3xl border border-[#E4DFEA] shadow-xs flex items-center justify-between">
                    <div className="space-y-1">
                        <span className="text-xs font-semibold text-[#665773]">Camera Mode</span>
                        <h4 className="text-xl font-extrabold text-[#2A2030]">✨ Pro Island Lens</h4>
                        <p className="text-[11px] text-[#93859E]">Filters and frames unlocked</p>
                    </div>
                    <div className="w-12 h-12 rounded-2xl bg-[#F9F7FB] border border-[#EFEAF3] flex items-center justify-center text-xl">
                        🎞️
                    </div>
                </div>

                <div className="p-6 bg-white rounded-3xl border border-[#E4DFEA] shadow-xs flex items-center justify-between">
                    <div className="space-y-1">
                        <span className="text-xs font-semibold text-[#665773]">Filter Album</span>
                        <div className="flex gap-1.5 pt-1">
                            {['All', 'Scenery', 'Residents'].map(cat => (
                                <button
                                    key={cat}
                                    onClick={() => setFilter(cat)}
                                    className={`px-3 py-1 rounded-xl text-xs font-semibold transition-colors cursor-pointer ${filter === cat ? 'bg-[#52435C] text-white' : 'bg-[#F6F4F8] text-[#665773] hover:bg-[#EAE2F0]'}`}
                                >
                                    {cat}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            {/* Main Polaroid Gallery Grid */}
            <div className="p-6 bg-white rounded-3xl border border-[#E4DFEA] shadow-xs space-y-4">
                <div className="flex justify-between items-center border-b border-[#F0EBF4] pb-4">
                    <h3 className="font-bold text-base text-[#2A2030] flex items-center gap-2">
                        <ImageIcon className="w-4.5 h-4.5 text-[#7A508C]" /> Pocket Camp Memories
                    </h3>
                    <span className="text-xs text-[#93859E]">{filteredMemories.length} photos displayed</span>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {filteredMemories.map(photo => (
                        <div key={photo.id} className="p-3 bg-[#F9F7FB] rounded-3xl border border-[#EFEAF3] shadow-xs space-y-3 group hover:border-[#D5C6E3] transition-all">
                            <div className={`w-full h-40 rounded-2xl bg-gradient-to-tr ${photo.gradient} flex items-center justify-center text-white text-xs font-semibold shadow-inner relative overflow-hidden`}>
                                <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#fff_1px,transparent_1px)] [background-size:12px_12px]"></div>
                                <span className="relative z-10 drop-shadow-sm">📸 {photo.title}</span>
                            </div>
                            <div className="px-1 flex justify-between items-start">
                                <div>
                                    <h4 className="font-bold text-xs text-[#2A2030]">{photo.title}</h4>
                                    <p className="text-[10px] text-[#93859E] flex items-center gap-1 mt-0.5">
                                        <Calendar className="w-2.5 h-2.5" /> {photo.date}
                                    </p>
                                </div>
                                <span className="text-[10px] bg-[#EAE2F0] text-[#7A508C] font-semibold px-2 py-0.5 rounded-full">
                                    {photo.tag}
                                </span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )
}